use std::panic::AssertUnwindSafe;

use console::{measure_text_width, style, Key, Style, Term};
use dialoguer::theme::ColorfulTheme;
use dialoguer::{Confirm, Input, MultiSelect, Select};

use crate::error::{BivvyError, Result};

use super::{Prompt, PromptOption, PromptResult, PromptType};

/// Convert dialoguer errors to BivvyError.
fn map_dialoguer_err(e: dialoguer::Error) -> BivvyError {
    BivvyError::Io(e.into())
}

/// Run a dialoguer prompt, catching any panics (e.g. from Ctrl+D/EOF).
fn catch_prompt_panic<F, T>(f: F) -> Result<T>
where
    F: FnOnce() -> std::result::Result<T, dialoguer::Error>,
{
    match std::panic::catch_unwind(AssertUnwindSafe(f)) {
        Ok(result) => result.map_err(map_dialoguer_err),
        Err(_) => Err(BivvyError::Io(std::io::Error::new(
            std::io::ErrorKind::Interrupted,
            "Prompt cancelled (EOF)",
        ))),
    }
}

